1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.validation.E164Telephone;
13	import org.springframework.samples.petclinic.util.AddressNormalizer;
14	import org.springframework.samples.petclinic.util.Regions;
15	
16	import java.util.Collection;
17	import java.util.List;
18	
19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
28	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
30	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
31	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
32	    @Mapping(target = "possibleDuplicate", expression = "java(formatPossibleDuplicate(owner))")
33	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
34	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
35	    OwnerDto toOwnerDto(Owner owner);
36	
37	    /**
38	     * Resolve an owner's possible-duplicate flag, coalescing a {@code null} stored value
39	     * (e.g. for owners created before the flag existed) to {@code false} so the response
40	     * always carries an explicit boolean.
41	     */
42	    default Boolean formatPossibleDuplicate(Owner owner) {
43	        if (owner == null) {
44	            return null;
45	        }
46	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
47	    }
48	
49	    /**
50	     * Derive an owner's age band from its {@code birthDate}, measured as the owner's age in whole
51	     * years on its {@code registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18
52	     * through 64, and {@code "SENIOR"} at 65 and over. Returns {@code null} when the owner, its
53	     * birth date or its registration date is absent, since the band cannot be derived without both
54	     * dates.
55	     */
56	    default String formatAgeBand(Owner owner) {
57	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
58	            return null;
59	        }
60	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
61	        if (age < 18) {
62	            return "MINOR";
63	        }
64	        if (age < 65) {
65	            return "ADULT";
66	        }
67	        return "SENIOR";
68	    }
69	
70	    /**
71	     * Derive an owner's preferred contact channel from its stored contact details:
72	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
73	     */
74	    default String formatContactPreference(Owner owner) {
75	        if (owner == null) {
76	            return null;
77	        }
78	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
79	        return hasEmail ? "EMAIL" : "PHONE";
80	    }
81	
82	    /**
83	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
84	     * (e.g. for owners created before the flag existed) to {@code false} so the response
85	     * always carries an explicit boolean.
86	     */
87	    default Boolean formatBulkSignupWarning(Owner owner) {
